def generate_next(n):
    if n < 10:
        return n + n
    else:
        product = 1
        has_non_zero_digit = False
        for digit in str(n):
            if digit != '0':
                product *= int(digit)
                has_non_zero_digit = True
        return n + product if has_non_zero_digit else n

def generate_series(seed):
    series = [seed]
    while True:
        next_value = generate_next(series[-1])
        if next_value in series:
            return len(series) - series.index(next_value)
        series.append(next_value)

